def get_ancestor(ancestors, node):
    left, middle, right = ancestors
    if node % 2 == 1 and brother(left, node):
        return left
    elif node % 2 == 0 and brother(right, node):
        return right
    else:
        if node <= middle // 2:
            return left
        return right

def brother(node, start_pos):
    if node > start_pos:
        return node - start_pos - 1
    return node - start_pos + 1

