from functools import lru_cache

def is_good_path(table):
    @lru_cache(maxsize=None)
    def dfs(r, c, count_a, count_b):
        if r == len(table) or c == len(table[0]):
            return count_a - count_b == 0
        if table[r][c] == 'a':
            return dfs(r, c + 1, count_a + 1, count_b) or dfs(r + 1, c, count_a, count_b + 1)
        else:
            return dfs(r, c + 1, count_a, count_b + 1) or dfs(r + 1, c, count_a + 1, count_b)
    return dfs(0, 0, 0, 0)

