def get_lca(node1, node2, par1, par2):
    if node1 == node2:
        return node1

    if node1 < node2:
        if par1 != par2:
            node_temp = 2 * node1
        else:
            if node2 > node1:
                node_temp = node1
            else:
                node1 = node2
    else:
        if par1 != par2:
            node_temp = 2 * node2
        else:
            if node2 > node1:
                node1 = node2
            else:
                node_temp = node1

    return get_lca(node_temp, node2, par2, par1)

def solve(query_row, h):
    nodes = list(range(2 ** h - 1))
    score = -1
    for i in range(1, 2 ** h - 1 + 1):
        if query_row % 2 == 1:
            odd, even = nodes[:int(len(nodes)/2)], nodes[int(len(nodes)/2):]
            chosen = odd[(i // 2) - 1] if i >= 2 else even[0]
        else:
            odd, even = nodes[:int(len(nodes)/2)], list(reversed(nodes[int(len(nodes)/2):]))
            chosen = odd[i // 2 - 1] if i >= 2 else even[0]

        if get_lca(chosen, int(nodes[query_row]), nodes[query_row], nodes[(query_row + 1) % 421]) == chosen:
            score = chosen

    print(f'? {chosen} {int(nodes[query_row])} {nodes[(query_row + 1) % 421]}')
    nodes[int(nodes[query_row])] = nodes[query_row]
    nodes[(query_row + 1) % 421] = chosen
    query_row -= 1
    return score

