import sys

class Graph:
    def __init__(self, n):
        self.adj = [None] * n

    def add_edge(self, u, v):
        self.adj[u] = v
        self.adj[v] = u

def dfs(graph, parent, node, values, result):
    for child in graph.adj[node]:
        if child != parent:
            new_result = max(abs(values[child] - values[node]), result)
            dfs(graph, node, child, values, new_result)
            result = min(result, new_result)
    return result

def solve():
    t = int(input())
    for _ in range(t):
        n, q = map(int, input().split())
