from typing import List
from math import inf

def shortest_Dist_between_pair(A: List[List[int]], B: List[List[int]]) -> List[int]:
    result = [inf for _ in A]

    for i in range(len(A)):
        for pair, v in B:
            pair -= 1
            if pair < 0 or pair >= len(A):
                continue
            result[i] = min(result[i], 1 + v * abs(A[pair][0] - A[i][0]))
            if A[pair][0] == A[i][0]:
                result[i] = min(result[i], abs(A[pair][1] - A[i][1]) + v)

    return result

def find_shortest(f_for_P: List[int], A: List[int]) -> int:
    dp = {0: 0}
    for i in range(len(A)):
        if A[i][1] != f_for_P[i]:
            dp[i] = inf
    mval = []
    for j in range(len(A) // 2):
        for k in range(j, len(A) // 2):
            f = 1
            f += dp[j + k]
            mval += [min(mval[j], mval[k]) + f]
    return min(mval) 

