def powermod(a, b, m):
    result = 1
    a = a % m
    while b > 0:
        if b % 2 == 1:
            result = (result * a) % m
        b = b >> 1
        a = (a * a) % m
    return result%1000000007

def calculate_naive(n, p):
    ans = 0
    last = p * p
    for i in range(1, p):
        if i < (last/(p-i)) + 1:
            ans += (1 << i) % 1000000007
    return ans % 1000000007

def main():
    n, p = map(int, input().split())
    if not (n == 1 or p <= 1 or 2 <= n <= p <= 10**9):
        print("Invalid input. Please check n and p.")
        return

    if n == 1 and p <= 10**10:
        print("0")
        return
    if p < 10**9:
        print((1 << p - 1) % 1000000007)
        return

    res = 1
    for i in range(1, n//2):
        res = powermod(2, p - (i + 1), 1000000007) * powermod(2, 1, 1000000007) % 1000000007 * (1 << n - (n + 2 * i)) % 1000000007 * 2 % 1000000007

    return (res + calculate_naive(n, p)) % 1000000007

print(main())
