def max_cpi(n, x, scores):
    sorted_scores = sorted(enumerate(scores), key=lambda x: x[1])
    current_sum = 0
    best_sum = 0
    for i, (_, score) in enumerate(sorted_scores):
        current_sum += score
        if i >= x:
            best_sum += current_sum
        if i == x-1:
            if best_sum > current_sum:
                return best_sum / (i+1)
            else:
                return current_sum / (i+1)

