def checkPeriodic(arr):
    n = len(arr)
    for s in range(1, n):
        for l in range(n - s):
            subarray = arr[l:l+s]
            valid = all(arr[l + i] >= subarray[i] for i in range(s))
            if valid:
                valid_periodic = all(arr[i] >= subarray[i % s] for i in range(n))
                if valid_periodic:
                    yield l, s

