from collections import defaultdict

def recover_departments(n, pairs):
    # Step 1: Create an adjacency list for each department
    adj_list = [defaultdict(list) for _ in range(n)]

    # Step 2: Assign IDs to each department
    ids = {f'D{dep+1}': dep + 1 for dep in range(n)}

    # Step 3: Assign IDs to each employee
    index_to_id = {}
    employees = {f'E{i}': i for i in range(n)}
    id_to_employee = {id: emp for emp, id in employees.items()}

    # Step 4: Assign heads and links
    head = None
    for dep in range(n):
        for emp_id in adj_list[dep]:
            if not head:
                head = id_to_employee[id_to_employee[emp_id]]
            else:
                head = assign_head_to(dep=dep, head=head, assign=head)

    # Step 5: Assign contacts
    for dep1, dep2 in pairs:
        assign_contacts(dep1, dep2, adj_list, id_to_employee)

    return [' '.join([f'{dep_id} {id_to_employee[id]}' for dep_id, ids_online in ids.items() if dep_id == dep or dep in adj_list[dep].keys()]) for dep in range(n)]

def assign_head_to(dep, head, assign):
    if id_to_employee[head] in assign.values():
        head = assign.pop(id_to_employee[head])
    return head

def assign_contacts(dep1, dep2, adj_list, id_to_employee):
    if dep1 not in adj_list[dep2]:
        return
    adj_list[dep1][id_to_employee[id_to_employee[id_to_employee[dep1 if dep1 >= dep2 else dep2]]]] = dep1
    adj_list[dep2][id_to_employee[id_to_employee[id_to_employee[dep2 if dep2 <= dep1 else dep1]]]] = dep2

# Read input from stdin
