        res = 0
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            res = min(res, dfs(x + dx, y + dy, mask | (1 << (i - 1)), depth - 1) + abs(tiles[x][y] - current))
