from collections import defaultdict
from heapq import heappop, heappush

def dijkstra(graph, start, end, weight):
    min_cost = [float('inf') for _ in range(len(graph))]
    min_cost[start] = 0
    dist = {node: float('inf') for node in graph}
    dist[start] = 0

    priority_queue = [(0, start)]

    while priority_queue:
        current_cost, current_node = heappop(priority_queue)
        if current_cost > min_cost[current_node]:
            continue

        for neighbor, length in graph[current_node].items():
            full_cost = current_cost + length
            if full_cost < dist[neighbor]:
                dist[neighbor] = full_cost
                heappush(priority_queue, (full_cost, neighbor))
                min_cost[neighbor] = full_cost

    return dist[end], min_cost[end]

def minSwapRedBlackTreeToBeautifulGraph(n, x, vertices, edges):
    # Build the graph
    graph = defaultdict(dict)
    for start, end, weight in edges:
        graph[start][end] = weight
        graph[end][start] = weight

    min_swaps = 0

    # Determine if it's possible to make all nodes of same color using minimum E operations
    while graph[0].keys():
        visited = defaultdict(bool)
        queue = [(0, 0)]
        visited[0] = True

        while queue:
            current_weight, current_node = queue.pop(0)
            if current_weight > x:
                continue
            if not graph[current_node].keys():
                continue
            for neighbor, edge_weight in graph[current_node].items():
                if not visited[neighbor]:
                    visited[neighbor] = True
                    if current_weight + edge_weight < current_node:
                        current_node = current_weight + edge_weight
                    if current_node < x and neighbor not in visited and neighbor not in graph[current_node]:
                        visited[neighbor] = True
                        queue.append((current_node, neighbor))
                        if neighbor not in graph[current_node]:
                            graph[current_node][neighbor] = edge_weight
                            if neighbor not in graph[0]: 
                                graph[0][neighbor] = edge_weight
                            else:
                                if graph[0][neighbor] > edge_weight:
                                    graph[0][neighbor] = edge_weight
            if current_weight >= x and neighbor not in graph[0]:
                graph[0][neighbor] = current_weight
                if neighbor not in graph[0]:
                    graph[0][neighbor] = current_weight
            else: 
                if visited[current_node]: 
                    return min_swaps + 1

    return -1

