import sys

def find_min_sum(N, Q):
    if Q == 0:
        return N

    # Given P, find the minimum sum of the first P elements that is still sortable
    min_sum = sys.maxsize
    for P in range(1, N + 1):
        if power_3(P) < N:
            if power_3(P) <= 1:
                min_sum = sys.maxsize
            else:
                min_sum = power_3(P - 1) + power_5(P) - power_3(P - 1) - power_6(P - 2)
                for power_2 in range(2, P + 2):
                    cur = power_3(P - 1) + power_5(P) - power_3(P - 1) - power_6(P - 2)
                    cur += power_2 * power(P - 1)
                    if cur < min_sum:
                        min_sum = cur
    return min_sum

def power_3(n):
    return sum((i-1)*(2*i+1) for i in range(1, n+1))

def power_5(n):
    return sum(n*2**k for k in range(n))

def power_6(n):
    return sum(n*3**k for k in range(n))

