def min_coins_for_jackpot(a, b, n):
    if abs(int(str(b[:-1]), 10) - int(str(a[:-1])) + 2) % 2 != 0:
        return -1

    dp = [[float('inf')] * n for _ in range(n)]
    memo = {}
    dp_helper = lambda x, y: min(dp_helper(x, y), dp[x][y]) if (x, y) not in memo else memo[(x, y)]

    def dp_helper(x, y):
        if x == 0 or y == 0:
            return 0 if x == 0 and y == 0 else float('inf')
        if dp[x][y] != float('inf'):
            return dp[x][y]
        memo[(x, y)] = min(dp_helper(x - 1, y), dp_helper(x, y - 1)) + 1
        dp[x][y] = memo[(x, y)]
        return dp_helper(x - 1, y) if dp_helper(x - 1, y) < dp_helper(x, y) else dp_helper(x, y - 1)

    total_moves = 0
    coins_needed = dp_helper(n - 1, n - 1)

    ans = []
    for _ in range(min(n - 1, 10**5)):
        if total_moves + dp_helper(n - 1, n - 1) >= 10**5:
            break
        if total_moves % 2 == 0 and dp_helper(n - 2, n - 1) != float('inf') or (total_moves % 2 != 0 and dp_helper(n - 1, n - 2) != float('inf')):
            ind = total_moves % 2
            new_a = str(int(str(a)) + int(str(b)[-ind]))
            ans.extend([(ind + i, -1 if (ind + i) < n - 1 else 1) for i in range(n - 1)])
            dp_helper(n - ind - 1, n - 1 + ind)
            total_moves += 1

    return coins_needed, ans[:10**5]
