import sys
from typing import Tuple

def read_input() -> Tuple[int, int, int]:
    n, l, r = map(int, sys.stdin.readline().split())
    return (n, l, r)

def find_closest_common_road_length(n: int, l: int, r: int, intersections: Tuple[int, ...]) -> Tuple[int, int]:
    closest_l_to_r_common = -1
    closest_r_to_l_common = -1

    # find l == r intersections
    for i, intersection in enumerate(intersections):
        road_path = intersections[intersection::]
        if len(set(intersections).intersection(road_path)) == r:
            return intersection, intersection

    # find l < r and l >= r intersections
    for i, intersection in enumerate(intersections):
        road_path = intersections[intersection::]
        if len(set(intersections).intersection(road_path)) > r:
            closest_l_to_r_common = intersection

    return closest_l_to_r_common, -1 if n == r else closest_r_to_l_common

def find_high_avg_beauty_path(n: int, l: int, r: int, intersections: Tuple[int, ...]) -> Tuple[int, int]:
    max_l_heavy_road = -1
    max_l_higheat_road = -1
    average_median, largest_average_median = -1, -1

    # find the largest average median
    for i, intersection in enumerate(intersections):
        road_path = intersections[intersection::]
        avg = sum(road_path) / len(road_path)
        if i % 2 == 0 and avg >= largest_average_median:
            largest_average_median = avg
            max_l_higheat_road = i

    # find the current average median with l ∈ [l, r]
    for i, intersection in enumerate(intersections):
        road_path = intersections[intersection::]
        if i % 2 == 0 and l <= len(road_path) <= r:
            avg_median = sum(road_path[:len(road_path)//2]) / (len(road_path)//2)
            if avg_median == largest_average_median and avg_median > average_median:
                average_median = avg_median
                max_l_heavy_road = len(road_path)//2
            elif avg_median > average_median:
                average_median = avg_median
                max_l_heavy_road = len(road_path)//2

    # determine valid paths for both l and r
    for forward_path_length in range(len(intersections)//2, max(1, r)):
        if r - forward_path_length > 1 and l - 1 > len(intersections):
            continue

        reverse_path_length = forward_path_length

        # decide whether the path contains heavy r > l shots
        if l <= len(intersections[:forward_path_length]) <= r:
            reverse_path_length -= max(1 - len(intersections[:max(0, r - forward_path_length - 2)]), len(intersections[:-1]))
        else:
            reverse_path_length -= max(1 - len(intersections[:len(intersections)//2]), len(intersections))

        # compute distance between the two endpoints
        distance = max(forward_path_length - l, 0), reverse_path_length - r
        valid, current_average = distance >= 0, distance[0] + distance[1] * intersections[distance[0]][distance[1]][0]

        # add the average to the max average median if it is larger than current max
        if valid and current_average > largest_average_median:
            largest_average_median = current_average
            max_l_heavy_road = max(0, max(-1 * min(forward_path_length, r - forward_path_length)))

    return max_l_heavy_road, max_l_higheat_road

if __name__ == "__main__":
    n, l, r = read_input()
    intersections = tuple(map(int, sys.stdin.read().split()))

    max_l_heavy_road, max_l_higheat_road = find_high_avg_beauty_path(n, l, r, intersections)

    print(find_closest_common_road_length(max_l_heavy_road, max_l_higheat_road, intersections))
