from itertools import islice

def find_min_sum_and_array(N, Q, P):
    ans = 0
    A = [0] * N
    for p in islice(P, 1, None):
        for c in range(1, log2(N)):
            if p << c > N:
                break
            index = p << 2 * c - N
            value = 2 * (2**(c-1) - 1 + int(p << c//2) % (2**(c-1) - 1)) + (-1)**(p>>c//2)
            new_value = A[index // 2] + value - A[index // 2]
            if new_value <= N:
                A[index // 2] = new_value
                ans += value
                if index != 0:
                    A[index // 2 + 1] = A[index // 2] + (-1)**(p >> c - (index // 2) - 1)
    return ans

