    for i in range(N):
        array[i] = i + 2
    return array

def next_array(prev_array):
    n = len(prev_array)
    result = []
    for i in range(n):
        count = (prev_array[i] - 1) // 2
        result.append(prev_array[i] - 2**count)
    return result

