        for neighbor in graph[node]:
            if visited[neighbor] == 0:
                visited[neighbor] = visited[node] + 1
                distance_from_start[neighbor] = visited[neighbor]
                queue.append(neighbor)

def get_minimum_operations(graph, tree, distance_from_end, weight):
    min_operations = float('inf')
    for start_node in range(1, len(tree)):
        visited = [0] * len(tree)
        bfs(graph, start_node, visited, distance_from_end)
        if visited[tree[0]] <= weight:
            distance_from_start = [0] * len(tree)
            bfs(graph, tree[0], visited, distance_from_start)
            min_operations = min(min_operations, visited[tree[0]] - distance_from_start[tree[0]])
    return min_operations

def main():
    n, x = map(int, input().split())
    colors = list(map(int, input().split()))
    tree = [[] for _ in range(n)]
    for _ in range(n - 1):
        u, v, w = map(int, input().split())
        tree[u - 1].append((w, v - 1))
        tree[v - 1].append((w, u - 1))
    distance_from_end = [float('inf')] * n
    for node in range(n):
        distance_from_end[node] = softmax(node)

    operations = get_minimum_operations(tree, colors, distance_from_end, x)
    print(1 if operations == float('inf') else operations)

def softmax(node):
    edges = []
    for _, neighbor in enumerate(tree[node]):
        edges.append(tree[node][neighbor][1])
    return max(edges) - min(edges)

if __name__ == "__main__":
    main()
