import collections
from math import comb

def factorial(n):
    return 1 if n in [0, 1] else n * factorial(n-1)

class ModularExponentiation:
    def __init__(self, mod):
        self.mod = mod
    def __call__(self, a, b):
        c = 1
        while b:
            if b % 2:
                c = (c*a % self.mod) % self.mod
            a = (a*a % self.mod)
            b //= 2
        return c

def moduli(p, m):
    return pow(m, p - 2, m)

def nCr(n, r, m):
    return factorial(n) * moduli(r, m) * moduli(n - r, m) % m

mod = 1000000007

def count_solutions(n, p):
    dp = collections.defaultdict(int)
    dp[0] = 1

    arr = [0] * n
    for i in range(n):
        arr[i] = combinations(n, i)
        dp[i+1] = moduli(arr[i], dp[i])

    num_apps = 0
    for a in arr:
        num_apps += (p - a) ** (n - a)

    return moduli(nCr(p, n, p), num_apps) * dp[n] % mod

def combinations(n, r):
    return factorial(n) // (factorial(r) * factorial(n - r))

for _ in range(int(input().strip())):
    n, p = map(int, input().strip().split(' '))
    print(count_solutions(n, p))
